import std/[threadpool, strutils]

proc transform(s: string): string =
  s.toUpperAscii()

when isMainModule:
  let words = @["hello", "nim", "concurrency"]
  var results = newSeq[FlowVar[string]](words.len)

  for i in 0..<words.len:
    results[i] = spawn transform(words[i])

  for i in 0..<results.len:
    echo ^results[i]

import std/threadpool

proc riskyTask(): int =
  raise newException(ValueError, "Something went wrong")

when isMainModule:
  let f = spawn riskyTask()
  try:
    discard ^f
  except ValueError as e:
    echo "Caught in main: ", e.msg
